import{QUESTOES_PATCIR_BIOPSIA as e,QUESTOES_PATCIR_CICATRIZACAO as t,QUESTOES_PATCIR_COMPLICACOES as n,QUESTOES_PATCIR_NEOPLASICA as r,QUESTOES_PATCIR_OPERATORIA as i}from"./bancoPatologiaCirurgica_part1-DcO0f6uM.js";import{QUESTOES_PATCIR_CONGELADOS as a,QUESTOES_PATCIR_CONGENITA as o,QUESTOES_PATCIR_DEGENERATIVA as s,QUESTOES_PATCIR_INFLAMATORIA as c,QUESTOES_PATCIR_TRAUMATICA as l}from"./bancoPatologiaCirurgica_part2-DY_7ylk8.js";var u={ENAV:{nome:`ENAV`,cor:`#1E40AF`},CESPE:{nome:`CESPE/Cebraspe`,cor:`#991B1B`},FCC:{nome:`FCC`,cor:`#166534`},VUNESP:{nome:`VUNESP`,cor:`#7C2D12`},AVAMEC:{nome:`AVAMEC`,cor:`#581C87`},CRMV:{nome:`CRMV`,cor:`#0E7490`},UFMG:{nome:`UFMG`,cor:`#4338CA`},UNESP:{nome:`UNESP`,cor:`#B45309`},USP:{nome:`USP`,cor:`#0F766E`},UFRRJ:{nome:`UFRRJ`,cor:`#BE185D`}},d={concurso:{nome:`Concurso Público`,cor:`#1E40AF`},residencia:{nome:`Residência Veterinária`,cor:`#9333EA`},enav:{nome:`ENAV`,cor:`#DC2626`},crmv:{nome:`Exame CRMV`,cor:`#0D9488`},pos:{nome:`Pós-Graduação`,cor:`#D97706`}},f={biopsia_exames:{nome:`Biópsia e Exames Histopatológicos`,eixo:`clin`},patologia_operatoria:{nome:`Patologia Operatoria`,eixo:`clin`},cicatrizacao_patologia:{nome:`Cicatrização e Patologia`,eixo:`clin`},complicacoes_cirurgicas:{nome:`Complicações Cirúrgicas`,eixo:`clin`},patologia_neoplasica_cirurgica:{nome:`Patologia Neoplásica Cirúrgica`,eixo:`clin`},patologia_traumatica:{nome:`Patologia Traumática`,eixo:`clin`},patologia_inflamatoria_cirurgica:{nome:`Patologia Inflamatória Cirúrgica`,eixo:`clin`},patologia_congenita:{nome:`Patologia Congênita`,eixo:`clin`},patologia_degenerativa:{nome:`Patologia Degenerativa`,eixo:`clin`},congelados_cortes:{nome:`Cortes Congelados e Citologia`,eixo:`clin`}},p=[{id:`patcir-001`,banca:`ENAV`,ano:2022,prova:`ENAV — Residência Cirurgia 2022`,tipo:`residencia`,topico:`biopsia_exames`,subtopico:`Tipos de biópsia`,dificuldade:`facil`,enunciado:`A biópsia é um procedimento essencial para o diagnóstico histopatológico em medicina veterinária. Sobre os tipos de biópsia, assinale a alternativa CORRETA:`,alternativas:[`A biópsia incisional consiste na remoção completa da lesão para análise histopatológica.`,`A biópsia excisional é indicada quando se deseja amostrar apenas uma porção da lesão para diagnóstico.`,`A biópsia por punch utiliza um instrumento cilíndrico que permite a obtenção de fragmentos de tecido com diâmetro padronizado.`,`A biópsia aspirativa por agulha fina (PAAF) fornece fragmentos teciduais suficientes para histopatologia convencional.`,`A biópsia incisional é contraindicada em lesões grandes, pois aumenta o risco de disseminação neoplásica.`],resposta_correta:`C`,explicacao:`A biópsia por punch utiliza um bisturi cilíndrico (punch) que permite a obtenção de fragmentos de tecido com diâmetros variados (2-8 mm), sendo útil para lesões cutâneas e mucosas. A biópsia incisional remove apenas parte da lesão (A errada). A biópsia excisional remove a lesão inteira (B errada). A PAAF fornece células isoladas, não fragmentos teciduais para histopatologia (D errada). A biópsia incisional é indicada justamente em lesões grandes para diagnóstico prévio (E errada).`},{id:`patcir-002`,banca:`CESPE`,ano:2021,prova:`CESPE — Médico Veterinário IBAMA 2021`,tipo:`concurso`,topico:`biopsia_exames`,subtopico:`Colorações histológicas`,dificuldade:`facil`,enunciado:`As colorações especiais são ferramentas fundamentais na histopatologia veterinária. Sobre a coloração de Hematoxilina-Eosina (H&E), assinale a alternativa CORRETA:`,alternativas:[`A hematoxilina cora estruturas ácidas (basófilas) em azul/violeta, enquanto a eosina cora estruturas básicas (acidófilas) em rosa.`,`A coloração H&E não permite a diferenciação entre núcleo e citoplasma celular.`,`A eosina é um corante catiônico que se liga a estruturas com carga positiva.`,`A hematoxilina cora preferencialmente o citoplasma e as fibras colágenas.`,`A coloração H&E não é utilizada em rotina laboratorial veterinária, sendo substituída por imuno-histoquímica.`],resposta_correta:`A`,explicacao:`A hematoxilina é um corante básico (catiônico) que cora estruturas ácidas (basófilas) como ácidos nucleicos (DNA/RNA) em azul/violeta. A eosina é um corante ácido (aniônico) que cora estruturas básicas (acidófilas) como proteínas citoplasmáticas em rosa. A H&E permite excelente diferenciação nuclear e citoplasmática (B errada). A eosina é aniônica, não catiônica (C errada). A hematoxilina cora núcleos, não citoplasma (D errada). A H&E é a coloração de rotina mais utilizada em histopatologia veterinária (E errada).`},{id:`patcir-003`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Residência Patologia 2023`,tipo:`residencia`,topico:`biopsia_exames`,subtopico:`Colorações especiais`,dificuldade:`medio`,enunciado:`As colorações especiais são recursos diagnósticos importantes na patologia cirúrgica veterinária. Sobre o Tricrômio de Masson, assinale a alternativa CORRETA:`,alternativas:[`O Tricrômio de Masson é indicado para a identificação de substância amiloide em tecidos.`,`No Tricrômio de Masson, o colágeno é corado em verde/azul, enquanto o músculo e citoplasma são corados em vermelho.`,`O Tricrômio de Masson utiliza apenas dois corantes: hematoxilina e eosina.`,`A coloração por Tricrômio de Masson não é útil na avaliação de processos fibróticos ou cicatriciais.`,`O Tricrômio de Masson é a coloração de escolha para identificar fungos em tecidos.`],resposta_correta:`B`,explicacao:`O Tricrômio de Masson é uma coloração especial que diferencia fibras colágenas (verde/azul) de músculo e citoplasma (vermelho), sendo fundamental para avaliar fibrose, processos fibróticos e neoformação de colágeno em feridas cirúrgicas e neoplasias. Para amiloide, utiliza-se Vermelho Congo ou rodamina (A errada). São três corantes: hematoxilina férrica, fucsina ácida e azul de anilina (C errada). É extremamente útil em processos fibróticos (D errada). Para fungos, utiliza-se PAS ou Grocott (E errada).`},{id:`patcir-004`,banca:`FCC`,ano:2020,prova:`FCC — Médico Veterinário SP 2020`,tipo:`concurso`,topico:`biopsia_exames`,subtopico:`Imuno-histoquímica`,dificuldade:`medio`,enunciado:`A imuno-histoquímica (IHQ) é uma técnica complementar de grande valor na patologia cirúrgica veterinária. Sobre seus princípios e aplicações, assinale a alternativa CORRETA:`,alternativas:[`A imuno-histoquímica utiliza anticorpos marcados para detectar antígenos específicos em tecidos fixados em formol e incluídos em parafina.`,`A imuno-histoquímica não pode ser realizada em tecidos fixados em formol, sendo exclusiva para tecidos frescos congelados.`,`Na imuno-histoquímica, o cromógeno DAB (diaminobenzidina) produz uma precipitação de cor azul, sendo o único utilizado.`,`A imuno-histoquímica não apresenta reações inespecíficas ou falsos positivos em tecidos veterinários.`,`A imuno-histoquímica é utilizada exclusivamente para o diagnóstico de neoplasias, não tendo aplicação em doenças inflamatórias.`],resposta_correta:`A`,explicacao:`A IHQ utiliza anticorpos primários específicos contra antígenos de interesse, seguidos de anticorpos secundários marcados com enzimas (peroxidase, fosfatase alcalina) ou fluoróforos, permitindo a detecção de antígenos em tecidos fixados em formol e incluídos em parafina (FFPE). O DAB produz precipitação marrom (C errada). A IHQ é aplicável a tecidos FFPE e congelados (B errada). Pode haver reações inespecíficas e falso-positivos (D errada). Tem aplicação em doenças infecciosas, inflamatórias e neoplásicas (E errada).`},{id:`patcir-005`,banca:`UNESP`,ano:2024,prova:`UNESP — Residência Patologia 2024`,tipo:`residencia`,topico:`biopsia_exames`,subtopico:`Processamento de tecidos`,dificuldade:`dificil`,enunciado:`O processamento histológico é etapa crucial para a qualidade do diagnóstico histopatológico. Sobre o processamento de tecidos em patologia cirúrgica veterinária, assinale a alternativa CORRETA:`,alternativas:[`A fixação em formol tamponado a 10% deve ser realizada por um período mínimo de 24 horas, sendo que espécimes maiores que 1 cm de espessura necessitam de maior tempo de fixação ou macroscopia prévia para redução do tamanho.`,`A desidratação alcoólica durante o processamento histológico deve iniciar diretamente com etanol absoluto para preservar melhor a morfologia celular.`,`O diafanização (clareamento) com xileno não é etapa necessária do processamento histológico convencional.`,`A inclusão em parafina deve ser realizada a temperaturas superiores a 70°C para garantir melhor permeação do tecido.`,`A fixação em formol tamponado a 10% é contraindicada para tecidos destinados a imuno-histoquímica, devendo-se utilizar apenas metanol.`],resposta_correta:`A`,explicacao:`A fixação em formol tamponado a 10% deve durar no mínimo 24 horas para espécimes pequenos. Fragmentos maiores que 1 cm de espessura necessitam de macroscopia (corte em fatias) para permitir a penetração adequada do fixador, ou tempos prolongados de fixação. A desidratação deve ser gradual (álcool 70% → 80% → 95% → absoluto) para evitar artefatos de retração (B errada). O diafanização é necessária para substituir o álcool por um solvente miscível com parafina (C errada). Temperaturas acima de 70°C causam artefatos de cozimento (D errada). O formol é compatível com IHQ, embora a fixação prolongada possa mascarar epítopos (E errada).`},{id:`patcir-006`,banca:`UFMG`,ano:2023,prova:`UFMG — Professor Cirurgia 2023`,tipo:`concurso`,topico:`patologia_operatoria`,subtopico:`Assepsia e contaminação`,dificuldade:`facil`,enunciado:`A classificação de contaminação de feridas cirúrgicas é fundamental para a conduta perioperatória. Sobre a classificação de contaminação de feridas, assinale a alternativa CORRETA:`,alternativas:[`Feridas limpas (classe I) são aquelas em que não há entrada em cavidades orgânicas e não há contaminação, com taxa de infecção esperada inferior a 5%.`,`Feridas contaminadas (classe III) apresentam contaminação microbiana mínima, com inflamação aguda sem supuração.`,`Feridas infectadas (classe IV) são aquelas com trauma recente com tecido desvitalizado, sem infecção prévia.`,`A classificação de contaminação não influencia a escolha do protocolo antibiótico perioperatório.`,`Feridas limpas-contaminadas (classe II) apresentam a maior taxa de infecção cirúrgica entre todas as classes.`],resposta_correta:`A`,explicacao:`Feridas limpas (classe I) são cirurgias eletivas sem entrada em cavidades orgânicas, sem inflamação e sem técnica asséptica comprometida, apresentando taxa de infecção < 5%. Feridas contaminadas (classe III) incluem trauma recente, entrada em trato gastrointestinal com vazamento ou técnica asséptica comprometida (B errada). Feridas infectadas (classe IV) apresentam infecção prévia, tecido necrótico ou perfuração visceral (C errada). A classificação orienta antibioticoprofilaxia (D errada). Feridas infectadas (classe IV) têm a maior taxa de infecção (E errada).`},{id:`patcir-007`,banca:`USP`,ano:2022,prova:`USP — Residência Cirurgia 2022`,tipo:`residencia`,topico:`patologia_operatoria`,subtopico:`Deiscência e infeccção de ferida`,dificuldade:`facil`,enunciado:`A deiscência cirúrgica é uma complicação temida no pós-operatório. Sobre seus fatores predisponentes em cães e gatos, assinale a alternativa CORRETA:`,alternativas:[`A hipoalbuminemia é um fator de risco significativo para deiscência, pois a albumina sérica abaixo de 2,0 g/dL compromete a cicatrização.`,`A deiscência ocorre exclusivamente por falha técnica do cirurgião, sem relação com fatores sistêmicos do paciente.`,`O uso de corticosteroides no pós-operatório não interfere na cicatrização e não é fator de risco para deiscência.`,`A deiscência é mais frequente no primeiro dia de pós-operatório, antes da fase proliferativa da cicatrização.`,`A contaminação bacteriana da ferida não é fator relevante para deiscência em cirurgias eletivas.`],resposta_correta:`A`,explicacao:`A hipoalbuminemia (albumina < 2,0 g/dL) é um fator de risco importante para deiscência, pois a albumina é essencial para a pressão osmótica, transporte de nutrientes e síntese de colágeno. Além da hipoalbuminemia, diabetes, uremia, uso de corticoides, infecção, anemia e má nutrição são fatores sistêmicos de risco (B errada). Corticosteroides inibem a fase inflamatória e proliferativa da cicatrização (C errada). A deiscência geralmente ocorre entre o 5º e o 10º dia de pós-operatório (D errada). A contaminação bacteriana é fator relevante mesmo em cirurgias eletivas (E errada).`},{id:`patcir-008`,banca:`AVAMEC`,ano:2021,prova:`AVAMEC — Residência Cirurgia 2021`,tipo:`residencia`,topico:`patologia_operatoria`,subtopico:`Seroma e hematoma`,dificuldade:`medio`,enunciado:`O seroma é uma complicação frequente no pós-operatório de cirurgias veterinárias. Sobre a fisiopatologia e manejo do seroma, assinale a alternativa CORRETA:`,alternativas:[`O seroma é uma coleção de sangue coagulado no espaço morto cirúrgico, resultante de hemorragia não controlada.`,`O seroma é uma coleção de exsudato seroso no espaço morto cirúrgico, resultante da resposta inflamatória local e quebra de tecidos.`,`O seroma ocorre exclusivamente em cirurgias contaminadas, não sendo observado em procedimentos limpos.`,`O espaço morto cirúrgico não contribui para a formação de seroma, sendo irrelevante seu fechamento.`,`O seroma deve ser sempre tratado com antibioticoterapia imediata, pois representa infecção ativa.`],resposta_correta:`B`,explicacao:`O seroma é uma coleção de exsudato seroso (líquido claro, amarelo-palha) que se forma no espaço morto cirúrgico devido à resposta inflamatória local, destruição tecidual e aumento da permeabilidade vascular. É a complicação mais comum após cirurgias de tecidos moles e ortopédicas. Hematoma é coleção de sangue coagulado (A errada). O seroma ocorre em qualquer tipo de cirurgia (C errada). O espaço morto é o principal fator predisponente (D errada). O seroma é estéril e não requer antibióticos; o tratamento é drenagem e compressão (E errada).`},{id:`patcir-009`,banca:`CRMV`,ano:2020,prova:`CRMV — Exame de Suficiência 2020`,tipo:`crmv`,topico:`patologia_operatoria`,subtopico:`Infecção de ferida cirúrgica`,dificuldade:`medio`,enunciado:`A infecção de ferida operatória (IFO) é uma das complicações mais relevantes em cirurgia veterinária. Sobre os fatores de risco para IFO em pequenos animais, assinale a alternativa CORRETA:`,alternativas:[`A duração prolongada do procedimento cirúrgico (acima de 90 minutos) é um fator de risco independente para IFO.`,`A antibioticoprofilaxia deve ser administrada após o fechamento da ferida para máxima eficácia.`,`A infecção de ferida operatória é sempre causada por bactérias Gram-negativas, sendo os cocos Gram-positivos irrelevantes.`,`O uso de drenos cirúrgicos não aumenta o risco de IFO, sendo protetor contra infecção.`,`A IFO em cirurgias limpas se manifesta obrigatoriamente nas primeiras 24 horas de pós-operatório.`],resposta_correta:`A`,explicacao:`A duração prolongada da cirurgia (acima de 90 minutos) é fator de risco independente para IFO, pois aumenta o tempo de exposição tecidual, a perda de calor corporal, a dessecação de tecidos e o tempo de contaminação. A antibioticoprofilaxia deve ser administrada 30-60 minutos antes da incisão (B errada). Staphylococcus spp. (Gram-positivos) são os principais agentes em cirurgias limpas (C errada). Drenos são fatores de risco por criar comunicação com o exterior (D errada). A IFO pode se manifestar até 30 dias após a cirurgia (E errada).`},{id:`patcir-010`,banca:`UFRRJ`,ano:2019,prova:`UFRRJ — Professor Cirurgia 2019`,tipo:`concurso`,topico:`patologia_operatoria`,subtopico:`Classificação de feridas`,dificuldade:`dificil`,enunciado:`A cicatrização de feridas cirúrgicas é influenciada por múltiplos fatores locais e sistêmicos. Sobre os fatores que comprometem a cicatrização de feridas operatórias em pequenos animais, analise as afirmativas:`,alternativas:[`A anemia (hematócrito < 20%) compromete a cicatrização por reduzir o aporte de oxigênio ao tecido, sendo a hipóxia tecidual local prejudicial à síntese de colágeno.`,`A hiperglicemia crônica (diabetes mellitus) não interfere na cicatrização, pois a glicose elevada facilita a proliferação celular.`,`O uso de anti-inflamatórios não esteroidais (AINEs) na fase inflamatória inicial pode retardar a cicatrização por inibir a prostaglandina E2.`,`A desidratação grave melhora a cicatrização por concentrar os fatores de crescimento no tecido lesado.`,`A contaminação bacteriana acima de 10^5 UFC/g de tecido é considerado limiar para infecção em feridas cirúrgicas.`],resposta_correta:`A`,explicacao:`A anemia grave (hematócrito < 20%) compromete a cicatrização por reduzir a capacidade de transporte de oxigênio, sendo a hipóxia tecidual prejudicial à hidroxilação da prolina e lisina na síntese de colágeno (reação dependente de O₂). A hiperglicemia prejudica funções de neutrófilos e síntese de colágeno (B errada). AINEs inibem COX e a produção de prostaglandinas necessárias para a fase inflamatória (C errada — mas a afirmativa está correta, porém não é a melhor resposta isolada). A desidratação prejudica a perfusão tecidual (D errada). O limiar de 10^5 UFC/g é correto para infecção em feridas (E errada — está correto, mas a questão pede a melhor resposta isolada sobre fatores sistêmicos; ambas A e E estão corretas, porém A aborda fator sistêmico mais abrangente).`},{id:`patcir-011`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Professor 2023`,tipo:`concurso`,topico:`cicatrizacao_patologia`,subtopico:`Fases da cicatrização`,dificuldade:`facil`,enunciado:`A cicatrização de feridas é um processo dinâmico e ordenado. Sobre as fases da cicatrização em pequenos animais, assinale a alternativa CORRETA:`,alternativas:[`A fase inflamatória ocorre nos primeiros 3-5 dias e é caracterizada por vasodilatação, exsudação e migração de leucócitos para o tecido lesado.`,`A fase proliferativa ocorre imediatamente após a lesão e é caracterizada pela contração da ferida e epitelização.`,`A fase de remodelação ocorre nos primeiros 3 dias e é caracterizada pela deposição de colágeno tipo III.`,`A fase inflamatória não é necessária para a cicatrização adequada e deve ser sempre suprimida.`,`As fases da cicatrização ocorrem de forma sequencial, sem sobreposição entre elas.`],resposta_correta:`A`,explicacao:`A fase inflamatória (0-5 dias) é caracterizada por vasodilatação, aumento da permeabilidade vascular, exsudação de proteínas plasmáticas e migração de neutrófilos e macrófagos, que limpam o tecido lesado e secretam citocinas pró-inflamatórias. A fase proliferativa ocorre do 3º ao 21º dia (B errada). A fase de remodelação começa após a 3ª semana e pode durar meses a anos (C errada). A fase inflamatória é essencial para o início da cascata de cicatrização (D errada). As fases se sobõem significativamente (E errada).`},{id:`patcir-012`,banca:`ENAV`,ano:2021,prova:`ENAV — Residência Cirurgia 2021`,tipo:`residencia`,topico:`cicatrizacao_patologia`,subtopico:`Fatores que afetam a cicatrização`,dificuldade:`facil`,enunciado:`Diversos fatores podem comprometer o processo de cicatrização em feridas cirúrgicas. Sobre o efeito da nutrição na cicatrização, assinale a alternativa CORRETA:`,alternativas:[`A vitamina C é essencial para a hidroxilação da prolina e lisina na síntese de colágeno, sendo sua deficiência causa de cicatrização retardada.`,`A deficiência de zinco não interfere na cicatrização, pois o zinco não participa de processos enzimáticos celulares.`,`A suplementação de vitamina A não é necessária em pacientes desnutridos, pois não interfere na cicatrização.`,`A proteína não é nutriente essencial para a cicatrização, pois o colágeno é formado exclusivamente por lipídios.`,`A desnutrição proteica não afeta a síntese de colágeno, apenas a velocidade de epitelização.`],resposta_correta:`A`,explicacao:`A vitamina C (ácido ascórbico) é cofator das enzimas prolil-hidroxilase e lisil-hidroxilase, essenciais para a hidroxilação da prolina e lisina na molécula de procollágeno. A deficiência de vitamina C (escorbuto) causa cicatrização retardada e fragilidade capilar. O zinco é cofator de metaloproteinases e DNA polimerase, sendo sua deficiência prejudicial (B errada). A vitamina A estimula a epitelização e síntese de colágeno (C errada). O colágeno é uma proteína (D errada). A desnutrição proteica compromete toda a cascata de cicatrização (E errada).`},{id:`patcir-013`,banca:`FCC`,ano:2022,prova:`FCC — Médico Veterinário RJ 2022`,tipo:`concurso`,topico:`cicatrizacao_patologia`,subtopico:`Queloides e hiperplasia cicatricial`,dificuldade:`medio`,enunciado:`Os queloides e a hiperplasia cicatricial são complicações da cicatrização. Sobre essas condições em cães, assinale a alternativa CORRETA:`,alternativas:[`Os queloides são cicatrizes que ultrapassam os limites da ferida original, sendo mais frequentes em gatos do que em cães.`,`A hiperplasia cicatricial é uma cicatriz elevada que permanece dentro dos limites da ferida original, sendo autolimitada.`,`Os queloides em cães são extremamente comuns, sendo a complicação mais frequente da cicatrização em caninos.`,`A hiperplasia cicatricial e o queloide são a mesma entidade patológica, diferindo apenas na localização anatômica.`,`Os queloides são mais frequentes em áreas de pele com baixa tensão, como o abdômen ventral.`],resposta_correta:`B`,explicacao:`A hiperplasia cicatricial é uma cicatriz elevada, eritematosa e pruriginosa que permanece confinada aos limites da ferida original e tende a regredir espontaneamente ao longo do tempo (autolimitada). Queloides ultrapassam os limites da ferida e são mais comuns em gatos (A errada — está parcialmente correta, mas queloides são incomuns em cães). Queloides são incomuns em cães (C errada). São entidades distintas: hiperplasia é autolimitada, queloide não (D errada). Queloides são mais frequentes em áreas de alta tensão (E errada).`},{id:`patcir-014`,banca:`UNESP`,ano:2020,prova:`UNESP — Professor Cirurgia 2020`,tipo:`concurso`,topico:`cicatrizacao_patologia`,subtopico:`Cicatrização por segunda intenção`,dificuldade:`medio`,enunciado:`A cicatrização por segunda intenção ocorre quando as bordas da ferida não são aproximadas cirurgicamente. Sobre esse processo em pequenos animais, assinale a alternativa CORRETA:`,alternativas:[`Na cicatrização por segunda intenção, a epitelização ocorre por migração de queratinócitos das bordas da ferida e de anexos cutâneos remanescentes.`,`A cicatrização por segunda intenção não apresenta fase de contração, sendo idêntica à cicatrização por primeira intenção.`,`A cicatrização por segunda intenção é sempre mais rápida que a cicatrização por primeira intenção.`,`A cicatrização por segunda intenção não ocorre em cães, sendo exclusiva de gatos.`,`A contração da ferida na cicatrização por segunda intenção é mediada exclusivamente por miofibroblastos, sem participação de fibroblastos.`],resposta_correta:`A`,explicacao:`Na cicatrização por segunda intenção, a epitelização ocorre por migração de queratinócitos das bordas da ferida e dos folículos pilosos e glândulas sebáceas remanescentes no leito da ferida, que funcionam como ilhotas de epitelização. A contração é uma característica marcante desse processo (B errada). É mais lenta que a primeira intenção devido ao maior volume de tecido a ser regenerado (C errada). Ocorre em todas as espécies (D errada). A contração é mediada por miofibroblastos, mas fibroblastos também participam ativamente (E errada).`},{id:`patcir-015`,banca:`USP`,ano:2024,prova:`USP — Pós-Graduação Cirurgia 2024`,tipo:`pos`,topico:`cicatrizacao_patologia`,subtopico:`Mecanismos moleculares`,dificuldade:`dificil`,enunciado:`A regulação molecular da cicatrização envolve múltiplos fatores de crescimento e citocinas. Sobre o papel do TGF-β (fator de crescimento transformador beta) na cicatrização de feridas em cães, assinale a alternativa CORRETA:`,alternativas:[`O TGF-β estimula a síntese de colágeno, a diferenciação de miofibroblastos e a deposição de matriz extracelular, sendo fundamental na fase proliferativa.`,`O TGF-β inibe a síntese de colágeno e a diferenciação de fibroblastos, sendo prejudicial à cicatrização.`,`O TGF-β atua exclusivamente na fase inflamatória, sem participação na fase proliferativa ou de remodelação.`,`O TGF-β é produzido exclusivamente por linfócitos T, sem participação de plaquetas, macrófibos ou fibroblastos.`,`O TGF-β não apresenta isoformas distintas, sendo uma única molécula com função uniforme em todos os tecidos.`],resposta_correta:`A`,explicacao:`O TGF-β (principalmente TGF-β1 e TGF-β2) é um potente estimulador da síntese de colágeno, diferenciação de miofibroblastos (a partir de fibroblastos), deposição de matriz extracelular e angiogênese. É produzido por plaquetas, macrófagos, fibroblastos e queratinócitos. Possui três isoformas (TGF-β1, β2, β3) com funções distintas. Atua em todas as fases da cicatrização, não apenas na inflamatória (C errada). É produzido por múltiplas células (D errada). Possui isoformas distintas (E errada).`},{id:`patcir-016`,banca:`CESPE`,ano:2023,prova:`CESPE — Médico Veterinário MAPA 2023`,tipo:`concurso`,topico:`complicacoes_cirurgicas`,subtopico:`Hemorragia`,dificuldade:`facil`,enunciado:`A hemorragia é uma complicação cirúrgica que pode comprometer a vida do paciente. Sobre os tipos de hemorragia em cirurgia veterinária, assinale a alternativa CORRETA:`,alternativas:[`A hemorragia arterial é caracterizada por sangue vermelho-vivo que jorra em jatos sincronizados com o pulso.`,`A hemorragia venosa é caracterizada por sangue vermelho-vivo que jorra em jatos pulsáteis.`,`A hemorragia capilar é o tipo mais grave de hemorragia cirúrgica, sendo responsável pela maioria dos óbitos.`,`A hemorragia arterial não requer controle cirúrgico imediato, pois se autolimita pela vasoconstrição reflexa.`,`A hemorragia venosa ocorre apenas em veias de grande calibre, como a veia cava cranial.`],resposta_correta:`A`,explicacao:`A hemorragia arterial é caracterizada por sangue vermelho-vivo (oxigenado) que jorra em jatos sincronizados com a sístole cardíaca (pulsátil). A hemorragia venosa apresenta sangue mais escuro, com fluxo contínuo e não pulsátil (B errada). A hemorragia capilar é a mais comum e menos grave (C errada). A hemorragia arterial requer controle imediato por risco de choque hipovolêmico (D errada). A hemorragia venosa ocorre em veias de qualquer calibre (E errada).`},{id:`patcir-017`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Residência Cirurgia 2020`,tipo:`residencia`,topico:`complicacoes_cirurgicas`,subtopico:`Choque`,dificuldade:`facil`,enunciado:`O choque é uma síndrome clínica caracterizada por perfusão tecidual inadequada. Sobre o choque hipovolêmico em pacientes cirúrgicos, assinale a alternativa CORRETA:`,alternativas:[`O choque hipovolêmico é causado por perda aguda de volume sanguíneo superior a 20-25% da volemia, resultando em hipotensão e taquicardia.`,`O choque hipovolêmico é caracterizado por bradicardia e hipertensão arterial.`,`O choque hipovolêmico em pequenos animais ocorre exclusivamente por hemorragias externas visíveis.`,`O lactato sérico não é um indicador confável de gravidade do choque hipovolêmico.`,`O choque hipovolêmico não ocorre em procedimentos cirúrgicos eletivos, apenas em traumas.`],resposta_correta:`A`,explicacao:`O choque hipovolêmico resulta da perda aguda de volume intravascular (hemorragia, desidratação grave, queimaduras) superior a 20-25% da volemia, causando diminuição do retorno venoso, débito cardíaco reduzido, hipotensão arterial e taquicardia compensatória. O lactato sérico é indicador sensível de hipoperfusão tecidual (D errada). Pode ocorrer por hemorragias internas ou externas (C errada). Pode ocorrer em cirurgias eletivas com complicações (E errada).`},{id:`patcir-018`,banca:`UFMG`,ano:2021,prova:`UFMG — Residência Cirurgia 2021`,tipo:`residencia`,topico:`complicacoes_cirurgicas`,subtopico:`Tromboembolismo`,dificuldade:`medio`,enunciado:`O tromboembolismo pulmonar (TEP) é uma complicação grave e potencialmente fatal no pós-operatório. Sobre o TEP em pequenos animais, assinale a alternativa CORRETA:`,alternativas:[`Os fatores de risco para TEP incluem imobilização prolongada, neoplasia, hiperadrenocorticismo e cirurgias ortopédicas extensas.`,`O TEP em cães é extremamente raro e não deve ser considerado como diagnóstico diferencial no pós-operatório.`,`O diagnóstico definitivo de TEP em pequenos animais é realizado exclusivamente por radiografia torácica.`,`A dispneia aguda no pós-operatório é sempre causada por pneumonia aspirativa, não devendo ser investigada como TEP.`,`O tratamento do TEP não inclui anticoagulação, sendo o manejo exclusivamente cirúrgico.`],resposta_correta:`A`,explicacao:`Os fatores de risco para TEP em pequenos animais incluem a tríade de Virchow (estase vascular, lesão endotelial, hipercoagulabilidade): imobilização prolongada, neoplasia, hiperadrenocorticismo, sírome nefrótica, sepse, cateteres venosos e cirurgias ortopédicas extensas. O diagnóstico é por TC angio ou cintilografia, não radiografia simples (C errada). A dispneia aguda deve incluir TEP no diagnóstico diferencial (D errada). O tratamento é anticoagulação com heparina (E errada).`},{id:`patcir-019`,banca:`USP`,ano:2019,prova:`USP — Concurso Professor 2019`,tipo:`concurso`,topico:`complicacoes_cirurgicas`,subtopico:`Fístula e abscesso`,dificuldade:`medio`,enunciado:`As fístulas e abscessos são complicações que podem surgir no pós-operatório. Sobre as fístulas em cirurgia veterinária, assinale a alternativa CORRETA:`,alternativas:[`A fístula salivar é uma complicação comum após cirurgias de sialoadenectomia, ocorrendo por lesão ou secção incompleta do ducto salivar.`,`As fístulas cutâneas são sempre de origem congênita, não podendo se formar no pós-operatório cirúrgico.`,`A fístula não apresenta comunicação com órgão cavitário ou superfície epitelial, diferindo do abscesso nesse aspecto.`,`O tratamento de fístulas cirúrgicas é sempre conservador, com antibioticoterapia isolada.`,`As fístulas perianais são exclusivas de gatos, não ocorrendo em cães.`],resposta_correta:`A`,explicacao:`A fístula salivar é complicação reconhecida após cirurgias na região cervical ventral, ocorrendo por lesão do ducto parotídeo, mandibular ou sublingual, resultando em acúmulo de saliva (sialocele) ou drenagem cutânea. As fístulas podem ser adquiridas no pós-operatório (B errada). A fístula se define pela comunicação entre dois epitélios ou entre órgão e superfície (C errada). O tratamento geralmente requer abordagem cirúrgica (D errada). Fístulas perianais são mais comuns em cães (E errada).`},{id:`patcir-020`,banca:`AVAMEC`,ano:2024,prova:`AVAMEC — Residência Cirurgia 2024`,tipo:`residencia`,topico:`complicacoes_cirurgicas`,subtopico:`Granuloma de corpo estranho`,dificuldade:`dificil`,enunciado:`O granuloma de corpo estranho é uma reação inflamatória crônica a materiais cirúrgicos ou corpos estranhos retidos. Sobre essa complicação em cães e gatos, analise as afirmativas:`,alternativas:[`O granuloma de corpo estranho é caracterizado histologicamente por infiltrado inflamatório granulomatoso com células gigantes multinucleadas, macrófagos epitelioides e fibrose periférica.`,`Os materiais de sutura absorvíveis não causam reação granulomatosa, sendo completamente inertes nos tecidos.`,`O granuloma de corpo estranho é sempre diagnosticado por radiografia simples, que mostra imagem radiopaca do material.`,`A reação granulomatosa a materiais cirúrgicos ocorre exclusivamente nas primeiras 48 horas de pós-operatório.`,`O granuloma de corpo estranho não necessita de tratamento cirúrgico, resolvendo espontaneamente em todos os casos.`],resposta_correta:`A`,explicacao:`O granuloma de corpo estranho é caracterizado histologicamente por inflamação granulomatosa com células gigantes do tipo corpo estranho (Langhans), macrófagos epitelioides, infiltrado linfoplasmocitário e fibrose reacional. Materiais absorvíveis também causam reação inflamatória local durante o processo de absorção (B errada). Corpos estranhos radiolucentes não são visíveis na radiografia simples (C errada). A reação pode surgir semanas a meses após a cirurgia (D errada). Geralmente requer remoção cirúrgica do material (E errada).`},{id:`patcir-021`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência Cirurgia 2024`,tipo:`residencia`,topico:`patologia_neoplasica_cirurgica`,subtopico:`Classificação TNM`,dificuldade:`facil`,enunciado:`O sistema TNM é o mais utilizado para o estadiamento de neoplasias. Sobre a classificação TNM em oncologia veterinária, assinale a alternativa CORRETA:`,alternativas:[`A letra T indica o tamanho e extensão do tumor primário, N indica o comprometimento de linfonodos regionais e M indica a presença de metástases à distância.`,`A letra T indica o tipo histológico do tumor, N indica o número de neoplasias e M indica a malignidade.`,`O sistema TNM não é aplicável à oncologia veterinária, sendo exclusivo da oncologia humana.`,`A classificação TNM avalia apenas o tamanho do tumor, sem considerar metástases ou linfonodos.`,`O sistema TNM é utilizado apenas para tumores epiteliais, não sendo aplicável a sarcomas.`],resposta_correta:`A`,explicacao:`O sistema TNM (Tumor-Nódulo-Metástase) é internacionalmente utilizado para estadiamento de neoplasias. T = tamanho e extensão do tumor primário (T1-T4), N = comprometimento de linfonodos regionais (N0-N2), M = metástases à distância (M0-M1). É aplicável a diversas neoplasias veterinárias (C errada). Avalia as três variáveis (D errada). É aplicável a carcinomas e sarcomas (E errada).`},{id:`patcir-022`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário DF 2022`,tipo:`concurso`,topico:`patologia_neoplasica_cirurgica`,subtopico:`Margens cirúrgicas`,dificuldade:`facil`,enunciado:`A avaliação de margens cirúrgicas é essencial para determinar a radicalidade da excisão tumoral. Sobre margens cirúrgicas em oncologia veterinária, assinale a alternativa CORRETA:`,alternativas:[`Margens cirúrgicas livres (negativas) indicam que não há células neoplásicas na borda do espécime cirúrgico, sugerindo excisão completa.`,`A avaliação de margens cirúrgicas não é necessária para tumores benignos, pois estes não recidivam.`,`Margens de 1 cm são adequadas para todos os tipos tumorais em pequenos animais, independentemente do grau de malignidade.`,`O conceito de margens cirúrgicas não se aplica a tecidos moles, sendo exclusivo de cirurgias ósseas.`,`A presença de margens comprometidas indica necessidade obrigatória de nova cirurgia em todos os casos.`],resposta_correta:`A`,explicacao:`Margens livres (negativas) significam ausência de células neoplásicas na periferia do espécime, indicando excisão completa. A margem recomendada varia conforme o tipo tumoral: 2-3 cm para mastocitomas de alto grau, 1-2 cm para sarcomas de baixo grau, 1 cm para tumores de baixo grau (C errada). Margens são avaliadas para qualquer neoplasia (B e D erradas). Margens comprometidas nem sempre indicam re-excisão; depende do tipo tumoral e resposta adjuvante (E errada).`},{id:`patcir-023`,banca:`FCC`,ano:2023,prova:`FCC — Médico Veterinário MG 2023`,tipo:`concurso`,topico:`patologia_neoplasica_cirurgica`,subtopico:`Biópsia de linfonodo sentinela`,dificuldade:`medio`,enunciado:`A biópsia de linfonodo sentinela (BLS) é uma técnica crescente em oncologia veterinária. Sobre seus princípios e indicações, assinale a alternativa CORRETA:`,alternativas:[`A BLS permite identificar o primeiro linfonodo de drenagem tumoral, auxiliando no estadiamento e evitando linfadenectomias desnecessárias.`,`A BLS é indicada apenas para tumores cutâneos, não sendo aplicável a neoplasias de mucosas.`,`A identificação do linfonodo sentinela é realizada exclusivamente por ultrassonografia, sem necessidade de corantes ou radiofármacos.`,`A BLS substitui completamente a avaliação histopatológica convencional de linfonodos regionais.`,`A BLS não apresenta limitações técnicas em pacientes com tumores previamente excisados.`],resposta_correta:`A`,explicacao:`A BLS identifica o primeiro linfonodo de drenagem linfática do tumor primário, permitindo avaliar a metastatização linfonodal com menor morbidade que a linfadenectomia radical. É utilizada com azul de metileno, azul patente ou radiofármacos (⁹⁹ᵐTc) associados a linfocintilografia (C errada). Aplicável a tumores cutâneos, mamários, orais e de mucosas (B errada). A avaliação histopatológica do linfonodo sentinela é complementar, não substitui (D errada). Cirurgias prévias podem alterar a drenagem linfática (E errada).`},{id:`patcir-024`,banca:`CRMV`,ano:2023,prova:`CRMV — Exame de Suficiência 2023`,tipo:`crmv`,topico:`patologia_neoplasica_cirurgica`,subtopico:`Estadiamento e prognóstico`,dificuldade:`medio`,enunciado:`O estadiamento tumoral é fundamental para a definição terapêutica e prognóstica. Sobre o estadiamento de neoplasias mamárias em cadelas, assinale a alternativa CORRETA:`,alternativas:[`O estadiamento de tumores mamários em cadelas inclui exames de imagem torácicos (radiografia ou TC) para avaliação de metástases pulmonares.`,`O estadiamento de neoplasias mamárias caninas não é necessário, pois todas as cadelas com tumor mamário devem ser submetidas à mesma cirurgia.`,`A citologia aspirativa por agulha fina é suficiente para o estadiamento completo de tumores mamários em cadelas.`,`O estadiamento tumoral é realizado apenas no pós-operatório, não havendo indicação de avaliação pré-cirúrgica.`,`A ultrassonografia abdominal não é útil no estadiamento de tumores mamários em cadelas.`],resposta_correta:`A`,explicacao:`O estadiamento de tumores mamários em cadelas segue o sistema TNM modificado e inclui: exame físico completo, hemograma, perfil bioquímico, radiografia torácica em 3 incidências (ou TC) para metástases pulmonares, ultrassonografia abdominal para metástases viscerais e citologia/biópsia do tumor primário. O estadiamento orienta o tipo de cirurgia (mastectomia parcial vs total) (B errada). A citologia não fornece estadiamento (C errada). O estadiamento é pré-operatório (D errada). A ultrassonografia é essencial para metástases viscerais (E errada).`},{id:`patcir-025`,banca:`UNESP`,ano:2022,prova:`UNESP — Professor Patologia 2022`,tipo:`concurso`,topico:`patologia_neoplasica_cirurgica`,subtopico:`Classificação histológica e grau`,dificuldade:`dificil`,enunciado:`A classificação histopatológica e o grau de malignidade são determinantes para o prognóstico e tratamento de neoplasias em pequenos animais. Sobre a classificação histológica de mastocitomas caninos, analise as afirmativas:`,alternativas:[`O sistema de Patnaik classifica mastocitomas caninos em graus I (bem diferenciado), II (moderadamente diferenciado) e III (pouco diferenciado), sendo o grau III associado ao pior prognóstico.`,`O sistema de Kiupel classifica mastocitomas em apenas dois graus (baixo e alto), sendo mais reprodutível que o sistema de Patnaik para subgrau II.`,`O grau histológico do mastocitoma não influencia a conduta cirúrgica, sendo todos tratados da mesma forma.`,`Mastocitomas grau I de Patnaik apresentam taxa de metástase superior a 80%, sendo os mais agressivos.`,`A imuno-histoquímica para KIT (CD117) não é utilizada no diagnóstico de mastocitomas, sendo específica para tumores de células dendríticas.`],resposta_correta:`A`,explicacao:`O sistema de Patnaik classifica mastocitomas em grau I (bem diferenciado, melhor prognóstico), II (intermediário) e III (pouco diferenciado, pior prognóstico). O sistema de Kiupel classifica em baixo e alto grau, mas é mais reprodutível para subgrau II do Patnaik (B errada). O grau histológico determina a margem cirúrgica necessária e a necessidade de terapia adjuvante (C errada). Grau I tem taxa de metástase < 10% (D errada). KIT (CD117) é o marcador imuno-histoquímico padrão para mastocitomas (E errada).`},{id:`patcir-026`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Residência Cirurgia 2022`,tipo:`residencia`,topico:`patologia_traumatica`,subtopico:`Fraturas`,dificuldade:`facil`,enunciado:`A classificação de fraturas é fundamental para a conduta ortopédica. Sobre os tipos de fraturas em pequenos animais, assinale a alternativa CORRETA:`,alternativas:[`A fratura cominutiva é aquela em que o osso se fragmenta em três ou mais fragmentos, frequentemente associada a trauma de alta energia.`,`A fratura em galho verde ocorre exclusivamente em animais adultos, pois o osso jovem é mais resistente.`,`A fratura exposta é aquela em que o osso fraturado não se comunica com o meio externo.`,`A fratura por estresse é causada por trauma agudo de alta velocidade, como atropelamento.`,`A classificação de AO/OTA não é utilizada em cirurgia veterinária, sendo exclusiva da ortopedia humana.`],resposta_correta:`A`,explicacao:`A fratura cominutiva caracteriza-se pela fragmentação do osso em três ou mais partes, geralmente causada por trauma de alta energia (atropelamento, queda de altura). A fratura em galho verde ocorre em ossos imaturos (filhotes), onde o osso se dobra e fratura parcialmente (B errada). A fratura exposta é quando há comunicação com o meio externo (C errada). A fratura por estresse é por sobrecarga repetitiva (D errada). A classificação AO/OTA é amplamente utilizada em veterinária (E errada).`},{id:`patcir-027`,banca:`ENAV`,ano:2020,prova:`ENAV — Residência Cirurgia 2020`,tipo:`residencia`,topico:`patologia_traumatica`,subtopico:`Luxações`,dificuldade:`facil`,enunciado:`As luxações articulares são lesões traumáticas comuns em pequenos animais. Sobre a luxação de patela medial em cães, assinale a alternativa CORRETA:`,alternativas:[`A luxação de patela medial é classificada em graus I a IV, sendo o grau IV aquele em que a patela permanece deslocada medialmente de forma permanente.`,`A luxação de patela medial ocorre apenas em cães de raças grandes, não sendo observada em raças miniatura.`,`O grau I de luxação de patela medial é o mais grave, com deslocamento permanente e incapacidade de extensão do joelho.`,`A luxação de patela medial não está associada a deformidades ósseas do membro, sendo exclusivamente ligamentar.`,`O tratamento cirúrgico da luxação de patela medial é contraindicado em filhotes, devendo ser aguardado até a maturidade esquelética.`],resposta_correta:`A`,explicacao:`A classificação de graus I-IV (Putnam) para luxação patelar medial: grau I = patela pode ser luxada manualmente mas se reduz espontaneamente; grau II = luxação intermitente com claudicação; grau III = patela permanece luxada mas pode ser reduzida manualmente; grau IV = patela permanentemente luxada com rotação da tíbia. É mais comum em raças pequenas (B errada). O grau I é o mais leve (C errada). Frequentemente associada a deformidades ósseas (D errada). A cirurgia precoce pode ser indicada em graus altos (E errada).`},{id:`patcir-028`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Residência Cirurgia 2021`,tipo:`residencia`,topico:`patologia_traumatica`,subtopico:`Rupturas tendíneas e ligamentares`,dificuldade:`medio`,enunciado:`A ruptura do ligamento cruzado cranial (LCCr) é a causa mais comum de claudicação de membro pélvico em cães. Sobre a patologia do LCCr em cães, assinale a alternativa CORRETA:`,alternativas:[`A ruptura do LCCr em cães é frequentemente multifatorial, envolvendo degeneração ligamentar prévia, conformação do joelho e obesidade.`,`A ruptura do LCCr em cães é sempre traumática, não havendo componente degenerativo.`,`O ligamento cruzado caudal (LCCc) é mais frequentemente rompido que o LCCr em cães.`,`A ruptura do LCCr não está associada a meniscopatia, sendo o menisco estrutura independente.`,`O diagnóstico de ruptura do LCCr é exclusivamente radiográfico, não sendo necessária a avaliação clínica.`],resposta_correta:`A`,explicacao:`A ruptura do LCCr em cães é multifatorial: degeneração ligamentar prévia (colágeno tipo III, deposição de cálcio, neovascularização), conformação angular do joelho (varo/valgo), obesidade, idade e predisposição racial. A degeneração ligamentar pré-dispõe à ruptura com trauma mínimo (B errada). O LCCr é mais frequentemente afetado que o LCCc (C errada). A lesão meniscal ocorre em 50-80% dos casos (D errada). O diagnóstico é clínico (teste de gaveta, compressão tibial) confirmado por TC ou artroscopia (E errada).`},{id:`patcir-029`,banca:`AVAMEC`,ano:2023,prova:`AVAMEC — Residência Cirurgia 2023`,tipo:`residencia`,topico:`patologia_traumatica`,subtopico:`Queimaduras`,dificuldade:`medio`,enunciado:`As queimaduras são lesões traumáticas que podem ter origem térmica, química ou elétrica. Sobre a classificação e fisiopatologia das queimaduras em pequenos animais, assinale a alternativa CORRETA:`,alternativas:[`As queimaduras de segundo grau superficial (2A) atingem a epiderme e derme superficial, apresentando bolhas e dor intensa, com preservação de folículos pilosos.`,`As queimaduras de terceiro grau preservam os anexos cutâneos (folículos pilosos, glândulas), permitindo a regeneração completa da pele.`,`As queimaduras de primeiro grau são as mais graves, apresentando necrose total da pele e ausência de dor.`,`A extensão corporal da queimadura não influencia o prognóstico, sendo apenas a profundidade relevante.`,`As queimaduras elétricas em cães causam apenas lesões superficiais, sem comprometimento de tecidos profundos.`],resposta_correta:`A`,explicacao:`Queimaduras de 2º grau superficial (2A) atingem epiderme e derme papilar, apresentando bolhas, eritema, dor à palpação e preservação de folículos pilosos e glândulas sudoríparas, permitindo regeneração em 14-21 dias. Queimaduras de 3º grau destroem todos os anexos cutâneos (B errada). Queimaduras de 1º grau são superficiais e dolorosas (C errada). A extensão corporal (regra dos 9s) é crucial para o prognóstico (D errada). Queimaduras elétricas causam necrose profunda por efeito Joule (E errada).`},{id:`patcir-030`,banca:`USP`,ano:2018,prova:`USP — Concurso Professor 2018`,tipo:`concurso`,topico:`patologia_traumatica`,subtopico:`Congelamento`,dificuldade:`dificil`,enunciado:`O congelamento (frostbite) é uma lesão traumática causada pela exposição a temperaturas extremamente baixas. Sobre a patologia do congelamento em animais domésticos, analise as afirmativas:`,alternativas:[`O congelamento causa formação de cristais de gelo intracelulares e extracelulares, resultando em desidratação celular, dano à membrana plasmática e necrose tecidual.`,`O congelamento atinge preferencialmente as extremidades (orelhas, ponta da cauda, almofadas digitais) por serem áreas de menor vascularização.`,`O reaquecimento rápido em água morna (37-39°C) é o tratamento de escolha, devendo ser evitado o reaquecimento lento.`,`As lesões de congelamento são exclusivamente reversíveis, não havendo risco de necrose tecidual permanente.`,`O congelamento não causa dor, sendo uma lesão indolor até a fase de reaquecimento.`],resposta_correta:`A`,explicacao:`O congelamento causa formação de cristais de gelo: inicialmente extracelulares (hipertonicidade extracelular → desidratação celular) e posteriormente intracelulares (destruição da membrana plasmática). As extremidades são mais vulneráveis por serem áreas de MAIOR perda de calor (B errada — são áreas de menor temperatura, mas a vascularização não é necessariamente menor). O reaquecimento deve ser rápido em água morna (37-39°C) (C errada — está correto, mas A é a resposta mais completa). Lesões profundas podem causar necrose permanente (D errada). A dor é intensa durante o reaquecimento (E errada).`},{id:`patcir-031`,banca:`FCC`,ano:2021,prova:`FCC — Médico Veterinário SP 2021`,tipo:`concurso`,topico:`patologia_inflamatoria_cirurgica`,subtopico:`Abscessos e flegmão`,dificuldade:`facil`,enunciado:`Abscessos e flegmões são processos inflamatórios infecciosos comuns em cirurgia veterinária. Sobre a diferenciação entre abscesso e flegmão, assinale a alternativa CORRETA:`,alternativas:[`O abscesso é uma coleção circunscrita de exsudato purulento, enquanto o flegmão é uma inflamação difusa do tecido conjuntivo com exsudação serosa ou purulenta.`,`O abscesso e o flegmão são a mesma entidade patológica, diferindo apenas na localização anatômica.`,`O flegmão é sempre causado por bactérias anaeróbicas, enquanto o abscesso é causado por aeróbicos.`,`O abscesso não apresenta cápsula fibrosa, sendo sempre uma coleção difusa de pus.`,`O flegmão é mais facilmente diagnosticado que o abscesso, pois apresenta flutuação evidente.`],resposta_correta:`A`,explicacao:`O abscesso é uma coleção circunscrita de exsudato purulento delimitada por uma cápsula de tecido de granulação (piogênica), enquanto o flegmão é uma inflamação difusa do tecido conjuntivo que se dissemina pelos planos teciduais sem delimitação clara. Ambos podem ser causados por aeróbicos e anaeróbicos (C errada). O abscesso pode ter cápsula fibrosa em estágios crônicos (D errada). O flegmão é mais difícil de diagnosticar por ser difuso, sem flutuação (E errada).`},{id:`patcir-032`,banca:`CRMV`,ano:2022,prova:`CRMV — Exame de Suficiência 2022`,tipo:`crmv`,topico:`patologia_inflamatoria_cirurgica`,subtopico:`Celulite`,dificuldade:`facil`,enunciado:`A celulite é uma infecção difusa dos tecidos moles que pode ser confundida com flegmão. Sobre a celulite em pequenos animais, assinale a alternativa CORRETA:`,alternativas:[`A celulite é uma infecção bacteriana difusa da pele e subcutâneo, caracterizada por eritema, edema, calor e dor, sem formação de abscesso delimitado.`,`A celulite ocorre exclusivamente em regiões de articulações, não acometendo outras áreas do corpo.`,`A celulite é sempre causada por fungos, sendo as bactérias irrelevantes na sua etiologia.`,`O diagnóstico de celulite é sempre confirmado por cultura bacteriana, não sendo possível o diagnóstico clínico.`,`A celulite não necessita de tratamento antibiótico, resolvendo espontaneamente em todos os casos.`],resposta_correta:`A`,explicacao:`A celulite é uma infecção difusa dos tecidos moles (pele e subcutâneo) caracterizada por sinais inflamatórios (eritema, edema, calor, dor) sem formação de coleção purulenta delimitada. Pode acometer qualquer região corporal (B errada). É mais frequentemente causada por bactérias (Staphylococcus, Streptococcus) (C errada). O diagnóstico é predominantemente clínico (D errada). Requer antibioticoterapia sistêmica (E errada).`},{id:`patcir-033`,banca:`UFMG`,ano:2024,prova:`UFMG — Residência Cirurgia 2024`,tipo:`residencia`,topico:`patologia_inflamatoria_cirurgica`,subtopico:`Fasciite necrosante`,dificuldade:`medio`,enunciado:`A fasciite necrosante é uma infecção necrosante dos tecidos moles de alta mortalidade. Sobre essa condição em cães, assinale a alternativa CORRETA:`,alternativas:[`A fasciite necrosante é caracterizada por necrose progressiva da fáscia e tecido subcutâneo, frequentemente polimicrobiana, com alta taxa de mortalidade.`,`A fasciite necrosante em cães é sempre causada por Streptococcus beta-hemolítico isolado, não havendo etiologia polimicrobiana.`,`A fasciite necrosante apresenta evolução lenta (semanas a meses), permitindo diagnóstico tardio sem comprometimento do prognóstico.`,`O diagnóstico de fasciite necrosante é exclusivamente clínico, não havendo indicação de exploração cirúrgica.`,`O tratamento da fasciite necrosante é exclusivamente clínico, com antibioticoterapia isolada sem necessidade de desbridamento cirúrgico.`],resposta_correta:`A`,explicacao:`A fasciite necrosante é uma infecção necrosante agressiva da fáscia e tecidos moles adjacentes, frequentemente polimicrobiana (anaeróbicos + aeróbicos), com destruição tecidual rápida e alta mortalidade (40-80% em humanos). O diagnóstico requer exploração cirúrgica para visualização da necrose fascial (D errada). O tratamento é emergencial com desbridamento cirúrgico radical + antibioticoterapia IV (E errada). Pode ser polimicrobiana (B errada). A evolução é rápida (horas a dias) (C errada).`},{id:`patcir-034`,banca:`UNESP`,ano:2023,prova:`UNESP — Residência Cirurgia 2023`,tipo:`residencia`,topico:`patologia_inflamatoria_cirurgica`,subtopico:`Osteomielite`,dificuldade:`medio`,enunciado:`A osteomielite é uma inflamação/infeccção do osso e medula óssea. Sobre a osteomielite bacteriana em cães, assinale a alternativa CORRETA:`,alternativas:[`A osteomielite bacteriana em cães é mais frequentemente causada por Staphylococcus pseudintermedius, frequentemente associada a fraturas abertas e osteossíntese.`,`A osteomielite em cães é sempre de origem fúngica, não havendo etiologia bacteriana.`,`A osteomielite ocorre exclusivamente em ossos longos, não acometendo vértebras ou ossos planos.`,`O diagnóstico de osteomielite é exclusivamente radiográfico, não sendo necessária a cultura bacteriana.`,`A osteomielite bacteriana não necessita de tratamento cirúrgico, sendo curada apenas com antibioticoterapia.`],resposta_correta:`A`,explicacao:`Staphylococcus pseudintermedius é o agente mais frequente de osteomielite bacteriana em cães, especialmente associada a fraturas abertas, osteossíntese (implantes) e mordidas. Pode acometer qualquer osso (C errada). A cultura e antibiograma são essenciais para terapia direcionada (D errada). O tratamento inclui antibioticoterapia prolongada + remoção de implantes/tecido necrótico (E errada). A etiologia bacteriana é a mais comum (B errada).`},{id:`patcir-035`,banca:`ENAV`,ano:2019,prova:`ENAV — Residência Cirurgia 2019`,tipo:`residencia`,topico:`patologia_inflamatoria_cirurgica`,subtopico:`Infecções de sítio cirúrgico`,dificuldade:`dificil`,enunciado:`A infecção de sítio cirúrgico (ISC) é uma complicação frequente em cirurgia veterinária. Sobre os mecanismos de patogenicidade das bactérias envolvidas em ISC em cães, analise as afirmativas:`,alternativas:[`O Staphylococcus pseudintermedius é o agente mais frequente em ISC de cirurgias limpas em cães, produzindo biofilmes que dificultam o tratamento com antibióticos.`,`A formação de biofilmes por Staphylococcus spp. em implantes ortopédicos não interfere na eficácia dos antibióticos, sendo facilmente erradicada.`,`A resistência a meticilina (MRSP) em Staphylococcus pseudintermedius é mediada pelo gene mecA, que codifica uma PBP2a com baixa afinidade pelos beta-lactâmicos.`,`Os Staphylococcus spp. coagulase-negativa não causam ISC em cães, sendo apenas contaminantes da microbiota cutânea.`,`A antibioticoprofilaxia de primeira escolha para cirurgias limpas em cães deve ser baseada em vancomicina para prevenir MRSP.`],resposta_correta:`A`,explicacao:`S. pseudintermedius é o principal agente de ISC em cirurgias limpas caninas, produzindo biofilmes polissacarídicos que dificultam a penetração de antibióticos e a ação do sistema imune. O gene mecA codifica PBP2a (C errada — está correta, mas A é mais completa). Biofilmes reduzem drasticamente a eficácia antibiótica (B errada). Staphylococcus coagulase-negativos podem causar ISC, especialmente em implantes (D errada). Vancomicina é reserva para MRSP, não primeira escolha (E errada).`},{id:`patcir-036`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso Professor 2021`,tipo:`concurso`,topico:`patologia_congenita`,subtopico:`Atresias`,dificuldade:`facil`,enunciado:`As atresias são malformações congênitas caracterizadas pela ausência ou obstrução de um orifício ou canal natural. Sobre as atresias em pequenos animais, assinale a alternativa CORRETA:`,alternativas:[`A atresia ani é uma malformação congênita em que o ânus está ausente ou obstruído, sendo mais comum em gatos e cães de raças pequenas.`,`A atresia ani ocorre exclusivamente em animais adultos, não sendo observada em neonatos.`,`A atresia ani é sempre acompanhada de fistula retovaginal em fêmeas.`,`O tratamento da atresia ani é sempre clínico, não havendo indicação cirúrgica.`,`A atresia ani não é uma condição hereditária, não havendo predisposição racial.`],resposta_correta:`A`,explicacao:`A atresia ani é uma malformação congênita em que o ânus está ausente ou obstruído por uma membrana (tipo I) ou por ausência do canal anal (tipo II-IV). É mais comum em gatos, cães de raças pequenas (Boston Terrier, Bulldog) e bovinos. Manifesta-se ao nascimento (B errada). Pode ou não estar associada a fístula retovaginal (C errada). O tratamento é cirúrgico (anoplastia, pull-through) (D errada). Há predisposição racial sugerindo componente genético (E errada).`},{id:`patcir-037`,banca:`UFRRJ`,ano:2022,prova:`UFRRJ — Residência Cirurgia 2022`,tipo:`residencia`,topico:`patologia_congenita`,subtopico:`Fístulas congênitas`,dificuldade:`facil`,enunciado:`As fístulas congênitas são comunicações anormais entre órgãos ou entre órgãos e a superfície corporal. Sobre a fístula perianal congênita em cães, assinale a alternativa CORRETA:`,alternativas:[`A fístula perianal congênita é uma comunicação anormal entre o reto e a pele perianal, sendo mais comum em Bulldogs Ingleses.`,`A fístula perianal congênita ocorre exclusivamente em gatos, não sendo descrita em cães.`,`A fístula perianal congênita não apresenta componente genético, sendo esporádica em todas as raças.`,`O tratamento da fístula perianal congênita é sempre conservador, com antibioticoterapia isolada.`,`A fístula perianal congênita não está associada a outras malformações anorretais.`],resposta_correta:`A`,explicacao:`A fístula perianal congênita (saculite/paraproctite congênita) é uma comunicação anormal entre o reto/ânus e a pele perianal, mais comum em Bulldogs Ingleses e Rhodesian Ridgeback, sugerindo predisposição genética. Ocorre em cães, raramente em gatos (B errada). Tem forte componente genético/ racial (C errada). O tratamento é cirúrgico (D errada). Pode estar associada a estenose anal e outras malformações (E errada).`},{id:`patcir-038`,banca:`USP`,ano:2020,prova:`USP — Residência Cirurgia 2020`,tipo:`residencia`,topico:`patologia_congenita`,subtopico:`Palatosquise`,dificuldade:`medio`,enunciado:`A palatosquise (fissura palatina) é uma malformação congênita comum em cães e gatos. Sobre sua fisiopatologia e tratamento, assinale a alternativa CORRETA:`,alternativas:[`A palatosquise pode ser classificada em primária (envolvendo lábio e palato duro anterior) e secundária (envolvendo palato mole e úvula), sendo mais comum em raças braquicefálicas.`,`A palatosquise ocorre apenas em gatos, não sendo observada em cães.`,`A palatosquise em filhotes não interfere na amamentação, sendo uma condição assintomática nos primeiros dias de vida.`,`O tratamento cirúrgico da palatosquise deve ser realizado imediatamente ao nascimento, sem espera por crescimento.`,`A palatosquise não apresenta componente genético, sendo exclusivamente ambiental.`],resposta_correta:`A`,explicacao:`A palatosquise é classificada em primária (fissura de lábio ± palato duro anterior) e secundária (fissura de palato mole ± úvula). É mais comum em raças braquicefálicas (Bulldog, Boxer, Shih Tzu) devido à conformação craniana. Ocorre em cães e gatos (B errada). Interfere na sucção e pode causar pneumonia aspirativa (C errada). A cirurgia é recomendada entre 3-4 meses quando há tamanho tecidual adequado (D errada). Há componente genético (E errada).`},{id:`patcir-039`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Residência Cirurgia 2022`,tipo:`residencia`,topico:`patologia_congenita`,subtopico:`Hérnias congênitas`,dificuldade:`medio`,enunciado:`As hérnias congênitas são protrusões de órgãos internos através de defeitos na parede corporal presentes ao nascimento. Sobre as hérnias congênitas em cães, assinale a alternativa CORRETA:`,alternativas:[`A hérnia umbilical é a hérnia congênita mais comum em cães, resultante do fechamento incompleto do anel umbilical.`,`A hérnia inguinal congênita ocorre exclusivamente em machos, não sendo observada em fêmeas.`,`A hérnia diafragmática congênita em cães é sempre fatal, não havendo sobrevida com tratamento cirúrgico.`,`A hérnia perineal congênita é mais comum em fêmeas, não acometendo machos.`,`As hérnias congênitas em cães não apresentam predisposição racial, ocorrendo igualmente em todas as raças.`],resposta_correta:`A`,explicacao:`A hérnia umbilical é a hérnia congênita mais frequente em cães, resultante da falha no fechamento do anel umbilical após o nascimento. Pode ser reduzível (contendo omento) ou não (alça intestinal encarcerada). A hérnia inguinal congênita é mais comum em fêmeas (B errada). A hérnia diafragmática congênita pode ser tratada cirurgicamente com sucesso (C errada). A hérnia perineal é mais comum em machos idosos, não congênita em fêmeas (D errada). Há predisposição racial (Shar-Pei, Weimaraner) (E errada).`},{id:`patcir-040`,banca:`CESPE`,ano:2020,prova:`CESPE — Médico Veterinário MAPA 2020`,tipo:`concurso`,topico:`patologia_congenita`,subtopico:`Persistência do canal arterial`,dificuldade:`dificil`,enunciado:`A persistência do canal arterial (PCA) é uma cardiopatia congênita comum em cães. Sobre sua fisiopatologia e abordagem cirúrgica, analise as afirmativas:`,alternativas:[`O canal arterial conecta a aorta à artéria pulmonar durante a vida fetal e normalmente se fecha nas primeiras 72 horas após o nascimento; sua persistência causa sobrecarga de volume no átrio e ventrículo esquerdos.`,`A PCA causa sobrecarga de pressão (não de volume) no ventrículo esquerdo, resultando em hipertrofia concêntrica.`,`O tratamento cirúrgico da PCA consiste na ligadura do canal com fio inabsorvível, sendo o método de escolha em cães de grande porte.`,`A PCA ocorre apenas em cães de raças grandes, não sendo observada em raças miniatura.`,`A PCA não é uma condição hereditária, não havendo predisposição racial em cães.`],resposta_correta:`A`,explicacao:`O canal arterial conecta a aorta à artéria pulmonar na vida fetal, permitindo o desvio do sangue dos pulmões. Após o nascimento, normalmente se fecha nas primeiras 24-72 horas. A persistência causa shunt esquerda-direita, sobrecarga de volume no coração esquerdo (dilatação excêntrica, não hipertrofia concêntrica — B errada). O tratamento é cirúrgico (ligadura ou oclusão com coils/Amplatz) (C errada — está correto, mas A é mais completa). Ocorre em todas as raças, com predisposição em Poodle, Collie, Pastor Alemão (D errada). Há predisposição racial/genética (E errada).`},{id:`patcir-041`,banca:`UNESP`,ano:2021,prova:`UNESP — Concurso Professor 2021`,tipo:`concurso`,topico:`patologia_degenerativa`,subtopico:`Artrose`,dificuldade:`facil`,enunciado:`A osteoartrite (artrose) é a doença articular degenerativa mais comum em cães. Sobre a patologia da osteoartrite canina, assinale a alternativa CORRETA:`,alternativas:[`A osteoartrite é caracterizada por degeneração progressiva da cartilagem articular, osteófitos, esclerose subcondral e sinovite crônica.`,`A osteoartrite é exclusivamente uma doença inflamatória aguda, sem componente degenerativo.`,`A osteoartrite ocorre apenas em cães idosos, não acometendo animais jovens.`,`O diagnóstico de osteoartrite é exclusivamente laboratorial, baseado em marcadores séricos.`,`A osteoartrite não afeta a cartilagem articular, comprometendo apenas as estruturas periarticulares.`],resposta_correta:`A`,explicacao:`A osteoartrite é uma doença articular degenerativa crônica caracterizada por: degeneração e perda progressiva da cartilagem hialina, formação de osteófitos marginais, esclerose do osso subcondral, sinovite crônica e alterações no líquido sinovial. É multifatorial, com componente degenerativo (B errada). Pode acometer animais jovens com displasia, trauma ou instabilidade articular (C errada). O diagnóstico é clínico + radiográfico (D errada). Afeta primariamente a cartilagem (E errada).`},{id:`patcir-042`,banca:`ENAV`,ano:2023,prova:`ENAV — Residência Cirurgia 2023`,tipo:`residencia`,topico:`patologia_degenerativa`,subtopico:`Espondilose deformante`,dificuldade:`facil`,enunciado:`A espondilose deformante é uma condição degenerativa da coluna vertebral comum em cães. Sobre sua patologia, assinale a alternativa CORRETA:`,alternativas:[`A espondilose deformante é caracterizada pela formação de osteófitos (bicos de papagaio) ao longo das vértebras, frequentemente nas articuições intervertebrais toracolombares.`,`A espondilose deformante afeta exclusivamente a região cervical, não acometendo a coluna toracolombar.`,`A espondilose deformante é sempre sintomática, causando claudicação neurológica em todos os casos.`,`A espondilose deformante ocorre apenas em cães de raças pequenas, não sendo observada em raças grandes.`,`A espondilose deformante não está associada à idade, ocorrendo igualmente em filhotes e adultos.`],resposta_correta:`A`,explicacao:`A espondilose deformante é uma condição degenerativa caracterizada pela formação de osteófitos (esporões ósseos) ao longo dos corpos vertebrais, mais comum na transição toracolombar. Frequentemente é assintomática (incidental radiográfica) (C errada). Afeta mais cães de raças grandes e idosos (D e E erradas). Pode acometer qualquer região da coluna (B errada).`},{id:`patcir-043`,banca:`FCC`,ano:2023,prova:`FCC — Médico Veterinário PR 2023`,tipo:`concurso`,topico:`patologia_degenerativa`,subtopico:`Mielopatia degenerativa`,dificuldade:`medio`,enunciado:`A mielopatia degenerativa (MD) é uma doença neurodegenerativa progressiva em cães. Sobre a mielopatia degenerativa canina, assinale a alternativa CORRETA:`,alternativas:[`A mielopatia degenerativa canina está associada a mutação no gene SOD1, sendo mais comum em Pastor Alemão e Welsh Corgi.`,`A mielopatia degenerativa canina afeta exclusivamente a região cervical da medula espinhal.`,`A mielopatia degenerativa canina é uma condição inflamatória aguda que responde ao tratamento com corticosteroides.`,`O diagnóstico de mielopatia degenerativa é exclusivamente clínico, não havendo teste genético disponível.`,`A mielopatia degenerativa canina não é progressiva, permanecendo estável ao longo do tempo.`],resposta_correta:`A`,explicacao:`A mielopatia degenerativa canina está associada a mutação no gene SOD1 (superóxido dismutase 1), mais prevalente em Pastor Alemão, Welsh Corgi, Boxer e Chesapeake Bay Retriever. Afeta a medula espinhal toracolombar (propriocepção, paraparesia progressiva → tetraplegia) (B errada). É neurodegenerativa, não inflamatória (C errada). O teste genético está disponível (D errada). É progressiva e incurável (E errada).`},{id:`patcir-044`,banca:`VUNESP`,ano:2024,prova:`VUNESP — Concurso Professor 2024`,tipo:`concurso`,topico:`patologia_degenerativa`,subtopico:`Osteocondrose`,dificuldade:`medio`,enunciado:`A osteocondrose é uma doença do desenvolvimento ósseo e cartilaginoso que afeta animais jovens em crescimento. Sobre a osteocondrose em cães de grande porte, assinale a alternativa CORRETA:`,alternativas:[`A osteocondrose é causada por falha na ossificação endocondral, resultando em espessamento da cartilagem articular que pode evoluir para osteocondrite dissecante (OCD).`,`A osteocondrose afeta exclusivamente o quadril (articulação coxofemoral), não acometendo ombro ou joelho.`,`A osteocondrose ocorre apenas em cães adultos com mais de 5 anos, sendo rara em filhotes.`,`A osteocondrose é sempre bilateral, não podendo acometer apenas um membro.`,`A osteocondrose não tem relação com a taxa de crescimento ou nutrição, sendo exclusivamente genética.`],resposta_correta:`A`,explicacao:`A osteocondrose resulta de falha na ossificação endocondral, causando espessamento anormal da cartilagem articular (osteocôndrose) que pode se descolar formando OCD (osteocondrite dissecante). Afeta ombro (mais comum), cotovelo, joelho e jarrete (B errada). Ocorre em cães jovens em crescimento (4-12 meses) (C errada). Pode ser unilateral (D errada). A nutrição (excesso de cálcio, energia) e crescimento rápido são fatores de risco (E errada).`},{id:`patcir-045`,banca:`CRMV`,ano:2024,prova:`CRMV — Exame de Suficiência 2024`,tipo:`crmv`,topico:`patologia_degenerativa`,subtopico:`Doença discal degenerativa`,dificuldade:`dificil`,enunciado:`A doença do disco intervertebral (DDIV) é a causa mais comum de mielopatia em cães. Sobre a classificação de Hansen e a patogenia da DDIV em cães, analise as afirmativas:`,alternativas:[`A DDIV tipo I de Hansen é caracterizada por extrusão aguda do núcleo pulposo calcificado, mais comum em raças condrodistróficas (Dachshund, Poodle).`,`A DDIV tipo II de Hansen é caracterizada por protrusão lenta do disco, mais comum em raças não condrodistróficas.`,`A DDIV tipo I e tipo II de Hansen são a mesma entidade patológica, diferindo apenas na localização anatômica.`,`O disco intervertebral cervical não é acometido por DDIV em cães, ocorrendo apenas na região toracolombar.`,`A DDIV tipo I de Hansen ocorre exclusivamente em cães idosos, sendo rara em animais jovens.`],resposta_correta:`A`,explicacao:`A DDIV tipo I de Hansen ocorre por extrusão aguda do núcleo pulposo degenerado/calcificado através do anel fibroso, causando compressão aguda da medula espinhal. É mais comum em raças condrodistróficas (Dachshund, Shih Tzu, Poodle, Beagle). A DDIV tipo II é protrusão gradual do disco (B errada). São entidades distintas (C errada). O disco cervical também é acometido (Derrada). Tipo I pode ocorrer em animais jovens (3-6 anos) (E errada).`},{id:`patcir-046`,banca:`UFRRJ`,ano:2023,prova:`UFRRJ — Residência Patologia 2023`,tipo:`residencia`,topico:`congelados_cortes`,subtopico:`Técnica de corte congelado`,dificuldade:`facil`,enunciado:`O corte congelado (frozen section) é uma técnica de histopatologia intraoperatória. Sobre seus princípios e indicações, assinale a alternativa CORRETA:`,alternativas:[`O corte congelado permite a obtenção de diagnóstico histopatológico em minutos durante o ato cirúrgico, auxiliando na definição de margens e conduta.`,`O corte congelado é uma técnica exclusiva para diagnóstico de neoplasias ósseas, não sendo aplicável a tecidos moles.`,`A qualidade morfológica do corte congelado é superior à do processamento convencional por inclusão em parafina.`,`O corte congelado não requer criostato, sendo realizada em microtomo comum.`,`O corte congelado não apresenta artefatos técnicos, fornecendo imagens histológicas perfeitas.`],resposta_correta:`A`,explicacao:`O corte congelado permite diagnóstico em minutos, sendo essencial para avaliação intraoperatória de margens cirúrgicas, diagnóstico de linfonodo sentinela e decisão sobre extensão da cirurgia. É aplicável a qualquer tecido de tecidos moles (B errada). A qualidade é inferior ao processamento convencional (C errada). Requer criostato para congelação e corte (D errada). Apresenta artefatos de congelação (cristais de gelo) (E errada).`},{id:`patcir-047`,banca:`USP`,ano:2022,prova:`USP — Residência Patologia 2022`,tipo:`residencia`,topico:`congelados_cortes`,subtopico:`Indicações e limitações`,dificuldade:`facil`,enunciado:`O exame de corte congelado intraoperatório apresenta indicações e limitações específicas. Sobre as indicações do corte congelado em cirurgia veterinária, assinale a alternativa CORRETA:`,alternativas:[`As principais indicações do corte congelado incluem avaliação de margens cirúrgicas, diagnóstico de linfonodo sentinela e diferenciação entre lesão neoplásica e inflamatória.`,`O corte congelado é indicado para diagnóstico definitivo de todos os tipos tumorais, sendo substituto completo do processamento convencional.`,`O corte congelado é indicado apenas para tumores cutâneos, não sendo aplicável a tumores viscerais.`,`O corte congelado não apresenta limitações diagnósticas, sendo 100% concordante com o diagnóstico final por parafina.`,`O corte congelado é contraindicado em tecidos com suspeita de infecção, devendo ser utilizado apenas em neoplasias.`],resposta_correta:`A`,explicacao:`As principais indicações do corte congelado são: avaliação de margens cirúrgicas intraoperatórias, diagnóstico de linfonodo sentinela, diferenciação entre lesão neoplásica e inflamatória, e confirmação de representatividade da amostra. Não substitui o diagnóstico definitivo por parafina (B errada). É aplicável a qualquer tecido (C errada). A concordância é de 85-95% (Derrada). Não é contraindicado para infecções (E errada).`},{id:`patcir-048`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Residência Patologia 2020`,tipo:`residencia`,topico:`congelados_cortes`,subtopico:`Artefatos`,dificuldade:`medio`,enunciado:`Os artefatos técnicos são comuns em cortes congelados e podem comprometer a interpretação histopatológica. Sobre os artefatos do corte congelado, assinale a alternativa CORRETA:`,alternativas:[`Os cristais de gelo são artefatos comuns em cortes congelados, resultantes da congelação inadequada do tecido, formando vacúolos claros que simulam edema ou vacuolização celular.`,`Os artefatos de cristais de gelo não comprometem a interpretação histológica, sendo cosméticos.`,`O artefato de margem de corte é exclusivo do processamento por parafina, não ocorrendo em cortes congelados.`,`Os artefatos em cortes congelados não afetam a coloração, mantendo a mesma intensidade que o processamento convencional.`,`A fixação em formol não é necessária para cortes congelados, não havendo artefatos de fixação.`],resposta_correta:`A`,explicacao:`Os cristais de gelo se formam quando a congelação é lenta ou inadequada, criando vacúolos claros no tecido que podem simular edema intracelular, vacuolização citoplasmática ou perda nuclear. São artefatos significantes que comprometem a interpretação (B errada). Artefatos de margem ocorrem em ambas as técnicas (C errada). A coloração pode ser mais intensa ou irregular (D errada). A fixação pode ser necessária para preservação (E errada).`},{id:`patcir-049`,banca:`ENAV`,ano:2021,prova:`ENAV — Residência Patologia 2021`,tipo:`residencia`,topico:`congelados_cortes`,subtopico:`Citologia aspirativa`,dificuldade:`medio`,enunciado:`A citologia aspirativa por agulha fina (CAAF) é uma ferramenta diagnóstica de primeira linha em oncologia veterinária. Sobre as vantagens e limitações da CAAF, assinale a alternativa CORRETA:`,alternativas:[`A CAAF é um método rápido, minimamente invasivo e de baixo custo, porém apresenta limitações na diferenciação entre neoplasias benignas e malignas de mesmo tipo histológico.`,`A CAAF fornece informações sobre a arquitetura tecidual, sendo equivalente à histopatologia convencional.`,`A CAAF não permite a diferenciação entre processos inflamatórios e neoplásicos.`,`A CAAF é contraindicada em tumores superficiais, devendo ser utilizada apenas em massas profundas.`,`A CAAF não apresenta limitações diagnósticas, sendo substituto completo da biópsia cirúrgica.`],resposta_correta:`A`,explicacao:`A CAAF é método diagnóstico rápido (resultado em minutos), minimamente invasivo (agulha 22-25G), de baixo custo e alto valor para triagem de massas. Limitações: não preserva arquitetura tecidual (B errada), dificuldade em diferenciar neoplasias do mesmo tipo histológico (ex.: carcinoma vs adenoma), amostragem limitada. Permite diferenciação inflamatório vs neoplásico (C errada). É indicada para massas superficiais e profundas (D errada). Não substitui biópsia para diagnóstico definitivo (E errada).`},{id:`patcir-050`,banca:`UFMG`,ano:2024,prova:`UFMG — Professor Patologia 2024`,tipo:`concurso`,topico:`congelados_cortes`,subtopico:`Interpretação de cortes congelados`,dificuldade:`dificil`,enunciado:`A interpretação de cortes congelados requer experiência e conhecimento dos artefatos técnicos inerentes à técnica. Sobre a interpretação de cortes congelados intraoperatórios em oncologia veterinária, analise as afirmativas:`,alternativas:[`A concordância diagnóstica entre corte congelado e processamento definitivo por parafina é de 85-95%, sendo os principais discordâncias observadas em tumores de baixo grau e lesões mesenquimais.`,`O corte congelado permite avaliação imuno-histoquímica confiável, sendo a IHQ de rotina realizada em amostras congeladas.`,`A interpretação de cortes congelados em tecidos com necrose extensa é mais confiável que em tecidos viáveis.`,`O corte congelado não apresenta limitações na diferenciação entre hiperplasia e neoplasia de baixo grau.`,`A concordância diagnóstica do corte congelado é de 100% em todos os tipos tumorais, sem discordâncias significativas.`],resposta_correta:`A`,explicacao:`A concordância entre corte congelado e diagnóstico definitivo é de 85-95%. As maiores discordâncias ocorrem em: tumores de baixo grau (bem diferenciados), lesões mesenquimais (sarcomas), lesões com necrose extensa e amostras pequenas/não representativas. A IHQ em cortes congelados é menos confiável que em parafina (B errada). Tecidos com necrose dificultam a interpretação (C errada). A diferenciação entre hiperplasia e neoplasia de baixo grau é desafiadora (D errada). A concordância não é 100% (E errada).`},...e,...i,...t,...n,...r,...l,...c,...o,...s,...a].filter(Boolean),m={totalQuestoes:p.length,porBanca:Object.entries(p.reduce((e,t)=>(e[t.banca]=(e[t.banca]||0)+1,e),{})).map(([e,t])=>({banca:e,total:t,...u[e]})),porAno:Object.entries(p.reduce((e,t)=>(e[t.ano]=(e[t.ano]||0)+1,e),{})).map(([e,t])=>({ano:Number(e),total:t})).sort((e,t)=>t.ano-e.ano),porTopico:Object.entries(p.reduce((e,t)=>(e[t.topico]=(e[t.topico]||0)+1,e),{})).map(([e,t])=>({topico:e,nome:f[e]?.nome,total:t})),porDificuldade:Object.entries(p.reduce((e,t)=>(e[t.dificuldade]=(e[t.dificuldade]||0)+1,e),{})).map(([e,t])=>({dificuldade:e,total:t}))};export{u as BANCAS,m as ESTATISTICAS_BANCO,p as QUESTOES_PATOLOGIA_CIRURGICA,d as TIPOS_PROVA,f as TOPICOS_PATOLOGIA_CIRURGICA};